data.mutation:
mutation D(
  $pCreate:[PurchaseOrderCreatePayloadInput!]!,
  $pUpdate:[PurchaseOrderUpdatePayloadInput!]!,
  $pDelete:[PurchaseOrderDeletePayloadInput!]!,
  $pCreateLine:[PurchaseOrderLineCreatePayloadInput!]!,
  $pUpdateLine:[PurchaseOrderLineUpdatePayloadInput!]!,
  $pDeleteLine:[PurchaseOrderLineDeletePayloadInput!]!,
){
  createPurchaseOrder(payload:$pCreate){id number}
  updatePurchaseOrder(payload:$pUpdate){ id }
  deletePurchaseOrder(payload:$pDelete){ id}
  createPurchaseOrderLine(payload:$pCreateLine){id number}
  updatePurchaseOrderLine(payload:$pUpdateLine){ id }
  deletePurchaseOrderLine(payload:$pDeleteLine){ id}

}

data.query:
query Query($where: PurchaseOrderWhereInput, $orderBy: [PurchaseOrderOrderByInput!], $first: Int, $after: String) {
  purchaseOrder(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        externalId
        note
        shipmentNumber
        issuedAt
        customData
        integrationData
        purchaseOrderType{id name}
        supplier{id code}
        facility{id code}
        purchaseOrderStatus{id name}
      }
    }
  }
}

query Query($where: PurchaseOrderLineWhereInput, $orderBy: [PurchaseOrderLineOrderByInput!], $first: Int, $after: String) {
  purchaseOrderLine(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        code
        rate
        description
        externalId
        lotNumber
        number
        dueAt
        shipAt
        purchaseOrder{id number}
        purchaseOrderLineStatus{id name}
        product{id code}
        productStrategyProcess{id code}
    quantity{value unit{id code}}
    balanceQuantity {value unit{id code}}
    pendingQuantity  {value unit{id code}}
    receivedQuantity {value unit{id code}}
      }
    }
  }
}

